impl Solution {
    pub fn add_negabinary(arr1: Vec<i32>, arr2: Vec<i32>) -> Vec<i32> {
        let mut res = Vec::new();
        let mut carry = 0;
        let mut i = arr1.len() as i32 - 1;
        let mut j = arr2.len() as i32 - 1;

        while i >= 0 || j >= 0 || carry != 0 {
            let a = if i >= 0 { arr1[i as usize] } else { 0 };
            let b = if j >= 0 { arr2[j as usize] } else { 0 };

            let sum = a + b + carry;
            let digit = sum % 2;
            carry = (sum - digit) / 2;

            res.push(digit);
            i -= 1;
            j -= 1;
        }

        // Remove leading zeros
        while res.len() > 1 && res.last().unwrap() == &0 {
            res.pop();
        }

        res.reverse();
        res
    }
}

